// Versão 1 da união: dois membros, e um consumidor que os trata a todos
type EventoV1 =
  | { tipo: "clique"; x: number; y: number }
  | { tipo: "tecla"; codigo: string };

function descreverV1(evento: EventoV1): string {
  switch (evento.tipo) {
    case "clique":
      return `clique em ${evento.x},${evento.y}`;
    case "tecla":
      return `tecla ${evento.codigo}`;
    default:
      return "evento desconhecido";
  }
}

console.log(descreverV1({ tipo: "tecla", codigo: "Enter" })); // "tecla Enter"

// Versão 2: alguém acrescentou "scroll" à união
type EventoV2 = EventoV1 | { tipo: "scroll"; delta: number };

// O consumidor ficou exatamente igual, e continua a compilar sem um único aviso
function descreverV2(evento: EventoV2): string {
  switch (evento.tipo) {
    case "clique":
      return `clique em ${evento.x},${evento.y}`;
    case "tecla":
      return `tecla ${evento.codigo}`;
    default:
      return "evento desconhecido";
  }
}

// O erro só aparece aqui, em execução, disfarçado de texto inofensivo
console.log(descreverV2({ tipo: "scroll", delta: 120 })); // "evento desconhecido"

type Pagamento =
  | { metodo: "cartao"; ultimos4: string }
  | { metodo: "mbway"; telemovel: string }
  | { metodo: "transferencia"; iban: string };

function referencia(pagamento: Pagamento): string {
  if (pagamento.metodo === "cartao") {
    // pagamento: { metodo: "cartao"; ultimos4: string }
    return `cartao ****${pagamento.ultimos4}`;
  }
  if (pagamento.metodo === "mbway") {
    // pagamento: { metodo: "mbway"; telemovel: string }
    return `mbway ${pagamento.telemovel}`;
  }
  if (pagamento.metodo === "transferencia") {
    // pagamento: { metodo: "transferencia"; iban: string }
    return `iban ${pagamento.iban}`;
  }
  // pagamento: never, porque já não sobra nenhum membro da união
  const sobra: never = pagamento;
  return String(sobra);
}

console.log(referencia({ metodo: "mbway", telemovel: "912345678" })); // "mbway 912345678"

type Estado = "pendente" | "pago" | "anulado";

function etiqueta(estado: Estado): string {
  switch (estado) {
    case "pendente":
      return "Pendente";
    case "pago":
      return "Pago";
    case "anulado":
      return "Anulado";
    default: {
      // todos os membros tratados: aqui estado é never e a atribuição passa
      const naoTratado: never = estado;
      return naoTratado;
    }
  }
}

console.log(etiqueta("pago")); // "Pago"

// A mesma função sem o caso "anulado"
function etiquetaIncompleta(estado: Estado): string {
  switch (estado) {
    case "pendente":
      return "Pendente";
    case "pago":
      return "Pago";
    default: {
      // @ts-expect-error falta tratar "anulado", por isso estado ainda é "anulado" e não never
      const naoTratado: never = estado;
      return naoTratado;
    }
  }
}

console.log(etiquetaIncompleta("pendente")); // "Pendente"

type Prioridade = "baixa" | "media" | "alta";

function casoImpossivel(valor: never): never {
  throw new Error(`Caso não tratado: ${String(valor)}`);
}

function minutosDeResposta(prioridade: Prioridade): number {
  switch (prioridade) {
    case "baixa":
      return 480;
    case "media":
      return 120;
    case "alta":
      return 15;
    default:
      return casoImpossivel(prioridade);
  }
}

console.log(minutosDeResposta("alta")); // 15

// Os dados que chegam de fora nunca passaram pelo compilador
const vindoDoServidor = JSON.parse('"urgente"') as Prioridade;

try {
  minutosDeResposta(vindoDoServidor);
} catch (erro) {
  console.log((erro as Error).message); // "Caso não tratado: urgente"
}

type Canal = "email" | "sms" | "push";

// Exaustividade num if/else encadeado: o else final recebe never
function portaDe(canal: Canal): number {
  if (canal === "email") {
    return 587;
  } else if (canal === "sms") {
    return 8080;
  } else if (canal === "push") {
    return 443;
  } else {
    const naoTratado: never = canal;
    return naoTratado;
  }
}

console.log(portaDe("push")); // 443

// Exaustividade por objeto de mapeamento
const etiquetas = {
  email: "Correio eletrónico",
  sms: "Mensagem",
  push: "Notificação",
};

function etiquetaDe(canal: Canal): string {
  return etiquetas[canal]; // ok: há uma chave para cada membro da união
}

console.log(etiquetaDe("sms")); // "Mensagem"

// A união cresceu, o objeto não: a indexação passa a ser rejeitada
type CanalAlargado = Canal | "webhook";

function etiquetaAlargada(canal: CanalAlargado): string {
  // @ts-expect-error o objeto não tem chave para "webhook"
  return etiquetas[canal];
}

console.log(etiquetaAlargada("email")); // "Correio eletrónico"

type NivelConhecido = "info" | "aviso" | "erro";

// Fronteira: o que chega é uma string qualquer, não um membro da união
function normalizarNivel(nivel: string): NivelConhecido | "outro" {
  switch (nivel) {
    case "info":
    case "aviso":
    case "erro":
      return nivel;
    default:
      // aqui nivel é string, não never: o desconhecido trata-se, não rebenta
      return "outro";
  }
}

console.log(normalizarNivel("aviso")); // "aviso"
console.log(normalizarNivel("debug")); // "outro"

