type Figura =
  | { forma: "circulo"; raio: number }
  | { forma: "quadrado"; lado: number }
  | { forma: "retangulo"; base: number; altura: number };

function casoImpossivel(valor: never): never {
  throw new Error(`Figura não tratada: ${JSON.stringify(valor)}`);
}

function area(figura: Figura): number {
  switch (figura.forma) {
    case "circulo":
      return Math.PI * figura.raio ** 2;
    case "quadrado":
      return figura.lado ** 2;
    case "retangulo":
      return figura.base * figura.altura;
    default:
      return casoImpossivel(figura);
  }
}

console.log(area({ forma: "quadrado", lado: 3 })); // 9
console.log(area({ forma: "retangulo", base: 2, altura: 5 })); // 10

// Um objeto que veio de fora e não respeita a união
const doJson = JSON.parse('{"forma":"triangulo","base":4,"altura":6}') as Figura;

try {
  area(doJson);
} catch (erro) {
  // 'Figura não tratada: {"forma":"triangulo","base":4,"altura":6}'
  console.log((erro as Error).message);
}

