type Comando =
  | { acao: "criar"; nome: string }
  | { acao: "apagar"; id: number }
  | { acao: "renomear"; id: number; nome: string };

function eComando(valor: unknown): valor is Comando {
  if (typeof valor !== "object" || valor === null) {
    return false;
  }
  const candidato = valor as { acao?: unknown; id?: unknown; nome?: unknown };
  if (candidato.acao === "criar") {
    return typeof candidato.nome === "string";
  }
  if (candidato.acao === "apagar") {
    return typeof candidato.id === "number";
  }
  if (candidato.acao === "renomear") {
    return typeof candidato.id === "number" && typeof candidato.nome === "string";
  }
  return false;
}

function casoImpossivel(valor: never): never {
  throw new Error(`Ação não tratada: ${JSON.stringify(valor)}`);
}

function executar(comando: Comando): string {
  switch (comando.acao) {
    case "criar":
      return `criado ${comando.nome}`;
    case "apagar":
      return `apagado ${comando.id}`;
    case "renomear":
      return `${comando.id} passou a ${comando.nome}`;
    default:
      return casoImpossivel(comando);
  }
}

function tratarMensagem(bruto: string): string {
  const dados: unknown = JSON.parse(bruto);
  if (!eComando(dados)) {
    return "mensagem ignorada"; // fronteira: o desconhecido é tolerado
  }
  return executar(dados); // daqui para dentro, exaustividade a sério
}

console.log(tratarMensagem('{"acao":"criar","nome":"notas"}')); // "criado notas"
console.log(tratarMensagem('{"acao":"renomear","id":7,"nome":"lista"}')); // "7 passou a lista"
console.log(tratarMensagem('{"acao":"reiniciar"}')); // "mensagem ignorada"
